import {
  Column,
  CreateDateColumn,
  Entity,
  ManyToOne,
  PrimaryColumn,
  Relation,
} from 'typeorm';

import { User } from '../../user/entities/index.js';

/** A User signed in on one device. See **Session** in CONTEXT.md. */
@Entity()
export class Session {
  // Generated by SessionService: the id goes into the tokens before the row exists
  @PrimaryColumn({ type: 'char', length: 36 })
  id: string;

  @ManyToOne(() => User, { nullable: false, onDelete: 'CASCADE' })
  user: Relation<User>;

  // SHA-256 (hex) of the current refresh token; anything else presented is reuse
  @Column({ type: 'char', length: 64 })
  refreshTokenHash: string;

  @Column()
  expiresAt: Date;

  @CreateDateColumn()
  createdAt: Date;

  @Column()
  lastUsedAt: Date;
}
